'use strict';
const el=id=>document.getElementById(id);let state={people:[],events:[]},selected='',invitationLinks=new Map();
const date=value=>new Date(value*1000).toLocaleString();
async function api(path,data){const response=await fetch('/api/library/'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Maha-Upload':'1'},body:JSON.stringify(data)});if(response.status===401){location.href='login.html';throw Error('Please sign in again.');}const result=await response.json();if(!response.ok)throw Error(result.error||(response.status===403?'Super user access is required.':'Could not save this change.'));return result;}
function person(){return state.people.find(p=>p.email===selected);}
function libraryStatus(p){if(p.user)return p.user.active?'Library account enabled':'Library account disabled';return p.invitation?{pending:'Invitation pending',expired:'Invitation expired',canceled:'Invitation canceled',accepted:'Invitation accepted'}[p.invitation.status]:'No invitation yet';}
function deviceStatus(d){return d.router_removed?'Router removal recorded':d.revoke_requested?'Router removal still required':d.tested?'Outside-network test recorded':d.router_created?'Device setup in progress':'Router profile not yet recorded';}
function remoteStatus(p){if(p.devices.some(d=>d.revoke_requested&&!d.router_removed))return 'Router removal required';if(p.mode==='local'&&!p.devices.some(d=>!d.router_removed))return 'At home only';if(!p.devices.length)return 'No remote devices recorded';const done=p.devices.filter(d=>d.tested&&!d.revoke_requested&&!d.router_removed).length;return done+' remote test'+(done===1?'':'s')+' recorded';}
function showMessage(text){el('message').textContent=text;}
async function reload(){state=await api('access');renderPeople();renderPerson();}
function renderPeople(){el('people').replaceChildren();for(const p of state.people){const button=document.createElement('button');button.className='person-card'+(p.email===selected?' active':'');const name=document.createElement('strong');name.textContent=p.email;const status=document.createElement('small');status.textContent=libraryStatus(p)+' · '+remoteStatus(p);button.append(name,status);button.onclick=()=>{selected=p.email;renderPeople();renderPerson();el('workspace').scrollIntoView({behavior:'smooth',block:'start'});};el('people').append(button);}if(!state.people.length)el('people').textContent='No setup plans yet.';}
function invitationBody(p,url){return 'You are invited to the MAHA library.\n\n'+(p.mode==='remote'?'REMOTE SETUP\n1. Install WireGuard from https://www.wireguard.com/install/ on each device.\n2. Import the separate private VPN configuration supplied for that device. Use endpoint '+state.endpoint+'. Do not share that configuration.\n3. Install the attached MAHA-Local-Root-CA.crt as a trusted CA certificate on the device. This lets your device trust certificates issued by MAHA.\n4. Turn off Wi-Fi on your phone, use cellular data, and enable WireGuard.\n\n':'AT-HOME SETUP\nConnect to the home network, then install the attached MAHA-Local-Root-CA.crt as a trusted CA certificate. This lets the device trust certificates issued by MAHA. A VPN is not required while at home.\n\n')+'CREATE YOUR LIBRARY ACCOUNT\n'+url+'\n\nThis invitation expires in 7 days and works once. Choose your own password of at least 12 characters.\n\nThen open '+state.libraryUrl+', sign in and open a book. There should be no certificate warning. If a warning appears, stop and contact me.\n\nYour library role is '+((p.invitation?.role||p.planned_role)==='super'?'Super user (manage books and access)':'User (browse and read)')+'.\n';}
function renderPerson(){const p=person();el('workspace').hidden=!p;if(!p)return;el('person-title').textContent=p.email;el('library-status').textContent=libraryStatus(p);el('vpn-status').textContent=remoteStatus(p);el('access-mode').value=p.mode;el('vpn-section').hidden=p.mode!=='remote'&&!p.devices.length;el('devices').replaceChildren();for(const d of p.devices){const card=document.createElement('div');card.className='device-card';const description=document.createElement('div');const heading=document.createElement('strong');heading.textContent=d.label;const detail=document.createElement('p');detail.textContent=(d.router_profile||'Router profile name not recorded')+' · '+(d.address?d.address+'/32':'Address not yet recorded');const status=document.createElement('p');status.textContent=deviceStatus(d);const button=document.createElement('button');button.className='secondary';button.textContent='Update checklist';button.onclick=()=>editDevice(d);description.append(heading,detail,status);card.append(description,button);el('devices').append(card);}if(!p.devices.length)el('devices').textContent='No devices recorded. Existing profiles can be added here without recreating them.';
el('invite-role').value=p.planned_role||'user';el('account-controls').hidden=!p.user;el('invite-controls').hidden=Boolean(p.user);if(p.user){el('account-role').value=p.user.role;el('account-active').checked=Boolean(p.user.active);el('invite-status').textContent='An account already exists. New devices do not need another library invitation.';}else{el('invite-status').textContent=p.invitation?libraryStatus(p)+(p.invitation.status==='pending'?' · expires '+date(p.invitation.expires):''):'Create the invitation when you are ready to send it.';el('create-invite').textContent=p.invitation?'Create replacement invitation':'Create invitation';}el('cancel-invite').hidden=!p.invitation||p.invitation.status!=='pending';const url=invitationLinks.get(p.email);el('invitation-actions').hidden=!url||Boolean(p.user)||p.invitation?.status!=='pending';if(url)el('email-invite').href='mailto:'+encodeURIComponent(p.email)+'?subject='+encodeURIComponent('Your invitation to the MAHA library')+'&body='+encodeURIComponent(invitationBody(p,url));el('events').replaceChildren();for(const action of state.events.filter(e=>e.email===p.email)){const row=document.createElement('li');const actor=state.people.find(p=>p.user?.id===action.actor)?.email;row.textContent=date(action.created)+' · '+action.event+(actor?' · '+actor:'');el('events').append(row);}if(!el('events').children.length)el('events').textContent='No actions recorded yet.';}
el('person-form').onsubmit=async event=>{event.preventDefault();try{const email=el('person-email').value.trim().toLowerCase();await api('access-person',{email,mode:el('person-mode').value,role:el('person-role').value});selected=email;await reload();showMessage('Setup plan saved. Continue with the checklist below.');el('workspace').scrollIntoView({behavior:'smooth'});}catch(error){showMessage(error.message);}};
el('mode-form').onsubmit=async event=>{event.preventDefault();try{const p=person();await api('access-person',{email:p.email,mode:el('access-mode').value,role:p.planned_role});await reload();showMessage('Access plan updated. Existing router profiles are unchanged.');}catch(error){showMessage(error.message);}};
el('create-invite').onclick=async()=>{const button=el('create-invite');button.disabled=true;try{const p=person();if(p.invitation?.status==='pending'&&!confirm('Replace the current invitation? Its previous link will stop working.'))return;const result=await api('invite',{email:p.email,role:el('invite-role').value,mode:p.mode});invitationLinks.set(p.email,location.origin+'/login.html#invite='+encodeURIComponent(result.token));await reload();showMessage('Invitation created. Email the prepared instructions and attach the public certificate.');}catch(error){showMessage(error.message);}finally{button.disabled=false;}};
el('cancel-invite').onclick=async()=>{try{await api('invite-revoke',{email:selected});invitationLinks.delete(selected);await reload();showMessage('Pending invitation canceled.');}catch(error){showMessage(error.message);}};
el('copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(invitationLinks.get(selected));showMessage('Invitation link copied.');}catch{showMessage('Could not copy the link. Use Email invitation instead.');}};
el('account-form').onsubmit=async event=>{event.preventDefault();try{const p=person();if(!el('account-active').checked){if(!confirm('Disable library access for '+p.email+'? VPN profiles must still be removed on the router.'))return;await api('access-disable',{email:p.email});}else await api('user',{id:p.user.id,role:el('account-role').value,active:true});await reload();showMessage('Library account updated. Review any outstanding router removals.');}catch(error){showMessage(error.message);}};
el('disable-access').onclick=async()=>{const p=person();if(!confirm('Disable library access and cancel pending invitations for '+p.email+'? Router profiles still require manual removal.'))return;try{await api('access-disable',{email:p.email});invitationLinks.delete(p.email);await reload();showMessage('Library access disabled. Remove flagged profiles from the router, then record each removal.');}catch(error){showMessage(error.message);}};
function editDevice(d={}){el('device-id').value=d.id||'';el('device-label').value=d.label||'';el('device-profile').value=d.router_profile||'';el('device-address').value=d.address?d.address+'/32':'';for(const [id,key] of [['created','router_created'],['shared','config_shared'],['certificate','certificate_installed'],['tested','tested'],['revoke','revoke_requested'],['removed','router_removed']])el('device-'+id).checked=Boolean(d[key]);el('device-heading').textContent=d.id?'Update device checklist':'Record a device';el('device-message').textContent='';el('device-dialog').showModal();}
el('add-device').onclick=()=>editDevice();el('device-close').onclick=()=>el('device-dialog').close();el('device-form').onsubmit=async event=>{event.preventDefault();const submit=event.submitter;if(submit)submit.disabled=true;try{const data={email:selected,label:el('device-label').value,routerProfile:el('device-profile').value,address:el('device-address').value,routerCreated:el('device-created').checked,configShared:el('device-shared').checked,certificateInstalled:el('device-certificate').checked,tested:el('device-tested').checked,requestRemoval:el('device-revoke').checked,routerRemoved:el('device-removed').checked};if(el('device-id').value)data.id=Number(el('device-id').value);await api('vpn-device',data);el('device-dialog').close();await reload();showMessage('Device checklist saved. Router settings were not changed by MAHA.');}catch(error){el('device-message').textContent=error.message;}finally{if(submit)submit.disabled=false;}};
reload().catch(error=>{showMessage(error.message);el('person-form').hidden=true;el('people').textContent='Access management is unavailable.';});
